import pathlib,subprocess,csv,json,hashlib
root=pathlib.Path('work/stage4_magma');mats=['GSE67835_Human_Cortex_woFetal','GSE87544_Mouse_Hypothalamus','PBMC_10x_68k','GSE98816_Mouse_Brain_Vascular','MouseCellAtlas_Muscle','TabulaMuris_FACS_Limb_Muscle'];report=[]
def table(p):
 lines=[x.split() for x in p.read_text().splitlines() if x.strip() and not x.startswith('#')];h=lines[0];return {r[0]:dict(zip(h,r)) for r in lines[1:]}
for mat in mats:
 before=root/('ye_ffs_'+mat+'.gsa.out');out=root/('verify_wide_'+mat);cmd=['work/magma_wide_sample_sum','--gene-results',str(root/'ye_ffs.genes.raw'),'--gene-covar',str(root/'matrices'/(mat+'.txt')),'--model','condition-hide=Average','direction=greater','--settings','abbreviate=0','--out',str(out)];r=subprocess.run(cmd,capture_output=True,text=True);assert r.returncode==0,(mat,r.stdout[-500:],r.stderr[-500:]);after=pathlib.Path(str(out)+'.gsa.out');a,b=table(before),table(after);assert a.keys()==b.keys();delta=max(abs(float(a[k]['P'])-float(b[k]['P'])) for k in a);assert delta<1e-10,(mat,delta);header=[x for x in after.read_text().splitlines() if 'MEAN_SAMPLE_SIZE' in x];report.append({'dataset':mat,'variables':len(a),'max_absolute_p_difference':delta,'corrected_output_mean_sample_size_header':header,'output_sha256':hashlib.sha256(after.read_bytes()).hexdigest()});print(mat,delta,header,flush=True)
# Relinked unmodified object code gives the same model output as the original binary on a representative human matrix.
mat=mats[0];out=root/'verify_relinked_reference';cmd=['work/magma_relinked_reference','--gene-results',str(root/'ye_ffs.genes.raw'),'--gene-covar',str(root/'matrices'/(mat+'.txt')),'--model','condition-hide=Average','direction=greater','--settings','abbreviate=0','--out',str(out)];r=subprocess.run(cmd,capture_output=True,text=True);assert r.returncode==0; a,b=table(root/('ye_ffs_'+mat+'.gsa.out')),table(pathlib.Path(str(out)+'.gsa.out'));assert a.keys()==b.keys();delta=max(abs(float(a[k]['P'])-float(b[k]['P'])) for k in a);assert delta<1e-10
pathlib.Path('outputs/stage4_magma_sample_sum_validation.json').write_text(json.dumps({'source_issue':'mean_sampsize uses 32-bit int total; signed overflow when summing constant N over many genes; affects printed MEAN_SAMPLE_SIZE metadata; code inspection found only output calls, not regression calls','actual_input_gene_N':386565,'patch':'change accumulator total from int to long long; leave count and missing code int','patched_source_sha256':hashlib.sha256(pathlib.Path('work/stage4_magma_setstats_patched.cpp').read_bytes()).hexdigest(),'patched_binary_sha256':hashlib.sha256(pathlib.Path('work/magma_wide_sample_sum').read_bytes()).hexdigest(),'results':report,'relinked_unmodified_representative_max_absolute_p_difference':delta,'caveat':'This checks the six observed results and this source-level fix, not all numerical correctness, data provenance or ancestry and model assumptions'},indent=2)+'\n')
print('unmodified relink representative delta',delta,flush=True)
